export class ValidationSamples {
 count: number = 0
 literal(): string {
  return "if (!ready) { return } this.count = 1"
 }
 comment(): string {
  // if (!ready) { return } this.count = 1
  return 'notes'
 }
 template(): string {
  return `if (!ready) { return } this.count = 1`
 }
 actual(ready: boolean): void {
  if (!ready) { return }
  this.count = 1
 }
 mixed(ready: boolean): void {
  /* if (!ready) { return } this.count = 9 */
  if (!ready) { return }
  this.count = 2
 }
 interpolationUnknown(): string {
  return `${this.count = 4}`
 }
}
